/* From Uiverse.io by bociKond - Source: https://dribbble.com/shots/21363706-Haze-Website-Log-in-Page - Tags: form, hover, focus, submit, label */
.__UIV_SCOPE__ form {
  --bg-light: #efefef;
  --bg-dark: #707070;
  --clr: #58BC82;
  --clr-alpha: #9c9c9c60;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  width: 100%;
}

.__UIV_SCOPE__ .form .input-span {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: .5rem;
}

.__UIV_SCOPE__ form input[type="email"],
.__UIV_SCOPE__ form input[type="password"] {
  border-radius: 0.5rem;
  padding: 1rem 0.75rem;
  width: 100%;
  border: none;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background-color: var(--clr-alpha);
  outline: 2px solid var(--bg-dark);
}

.__UIV_SCOPE__ form input[type="email"]:focus,
.__UIV_SCOPE__ form input[type="password"]:focus {
  outline: 2px solid var(--clr);
}

.__UIV_SCOPE__ .label {
  align-self: flex-start;
  color: var(--clr);
  font-weight: 600;
}

.__UIV_SCOPE__ form .submit {
  padding: 1rem 0.75rem;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  border-radius: 3rem;
  background-color: var(--bg-dark);
  color: var(--bg-light);
  border: none;
  cursor: pointer;
  transition: all 300ms;
  font-weight: 600;
  font-size: .9rem;
}

.__UIV_SCOPE__ form .submit:hover {
  background-color: var(--clr);
  color: var(--bg-dark);
}

.__UIV_SCOPE__ .span {
  text-decoration: none;
  color: var(--bg-dark);
}

.__UIV_SCOPE__ .span a {
  color: var(--clr);
}
